"""Size counts hand-written lines: tests included, generated files excluded (post-mortem 2026-10-11 §3)."""
import pytest

from factory import checks, size
from factory.pr_description import diff_stats

STATS = diff_stats("71\t0\tsrc/lib/models.ts\n532\t0\ttests/models.test.ts\n5084\t2445\tcatalog-watch/openrouter-models.json\n"
                   "59\t16\tcatalog-watch/report.md\n1200\t900\tbun.lock\n3\t1\tdocs/api/client.gen.ts\n")
BUDGET = size.DEFAULT_BUDGET


def test_budget_parsing_and_bands():
    assert size.parse_budget(None) == {"XS": 50, "S": 150, "M": 400}
    assert size.parse_budget("XS=30, s=100,M=300") == {"XS": 30, "S": 100, "M": 300}
    with pytest.raises(ValueError):
        size.parse_budget("S=500")
    assert [size.size_for(n, BUDGET) for n in (0, 50, 51, 150, 400, 401)] == ["XS", "XS", "S", "S", "M", "L"]


def test_gitattributes_lockfiles_and_spec_declared_regeneration():
    attrs = "# generated\ndocs/api/*.gen.ts linguist-generated\ncatalog-watch/report.md linguist-generated=true\n" \
            "bun.lock -linguist-generated\n"
    regenerated = [{"paths": ["catalog-watch/openrouter-models.json"], "command": "bun run catalog:refresh"}]
    m = size.measure(STATS, gitattributes=attrs, regenerated=regenerated)
    reasons = {f["path"]: f["reason"] for f in m["generated_files"]}
    assert reasons == {"catalog-watch/openrouter-models.json": "declared regenerated by the spec",
                       "catalog-watch/report.md": "marked linguist-generated in .gitattributes",
                       "docs/api/client.gen.ts": "marked linguist-generated in .gitattributes"}
    # a lockfile counts as generated unless .gitattributes says otherwise
    assert (m["app"], m["tests"], m["hand_written"]) == (71 + 2100, 532, 2703) and m["commands"] == ["bun run catalog:refresh"]
    assert {f["path"] for f in size.measure(STATS)["generated_files"]} == {"bun.lock"}


def test_size_line_and_flag():
    m = size.measure(STATS, regenerated=[{"paths": ["catalog-watch/**", "bun.lock"], "command": "bun run catalog:refresh"}])
    line = size.line(m, 120, BUDGET)
    assert line.startswith("607 hand-written lines (app 75, tests 532); 9704 generated lines in `catalog-watch/openrouter-models.json`, "
                           "`catalog-watch/report.md`, `bun.lock`, regenerated by `bun run catalog:refresh`. Estimated 120 (S;")
    assert line.endswith("**Over budget: 607 hand-written lines is above size M (≤ 400).**")
    small = size.measure(diff_stats("40\t0\tsrc/a.py\n30\t0\ttests/test_a.py\n"))
    assert size.flag(small, 40, BUDGET) == "Over budget: 70 hand-written lines is size S; the spec estimated 40 (size XS)."
    assert size.flag(small, 120, BUDGET) is None and "no generated files" in size.line(small, 120, BUDGET)


def test_planning_checks_refuse_work_above_m():
    dec = {"work_items": [{"work_item_id": "wi-a", "size": "S", "estimated_lines": 120},
                          {"work_item_id": "wi-b", "size": "M", "estimated_lines": 900}]}
    r = checks.decomposition_size(dec, BUDGET)
    assert not r.passed and "wi-b (900 lines)" in r.detail
    spec = {"estimated_size": "S", "estimated_lines": {"hand_written": 120, "app": 70, "tests": 50}}
    assert checks.spec_size_estimate(spec, BUDGET).passed
    assert not checks.spec_size_estimate({**spec, "estimated_lines": {"hand_written": 401, "app": 300, "tests": 101}}, BUDGET).passed
    assert "does not match" in checks.spec_size_estimate({**spec, "estimated_size": "XS"}, BUDGET).detail
    assert not checks.spec_size_estimate({}, BUDGET).passed


def test_merge_check_reports_and_never_fails(examples):
    from factory.stages.implement import deterministic_findings
    over = size.measure(diff_stats("900\t0\tsrc/a.py\n"))
    spec = {**examples["spec_smart_retries"], "estimated_lines": {"hand_written": 120, "app": 70, "tests": 50}}
    det = checks.run_all_for_merge(spec=spec, changed_files=["src/a.py"], deleted_files=[], existing_test_files=[], added_lines_by_file={},
                                   implementation_report={}, passing_tests=None, command_results=[], size=over, size_budget_lines=BUDGET)
    [r] = [d for d in det if d.check == "size_budget"]
    assert r.passed and r.flag.startswith("Over budget: 900") and r.to_dict()["flag"] == r.flag
    assert not any(f["finding_id"] == "DET-size_budget" for f in deterministic_findings(det))
    assert "flag" not in checks.size_budget(size.measure(diff_stats("10\t0\tsrc/a.py\n")), 120, BUDGET).to_dict()


def test_onboarding_asks_to_mark_generated_files(tmp_path, root):
    from factory.onboarding import GENERATED_QUESTION, generated_files_question
    plan = {"questions": [], "files": [], "generated_files": [
        {"path": "catalog-watch/openrouter-models.json", "evidence": "written by scripts/catalog.ts", "regenerated_by": "bun run catalog:refresh"}]}
    asked = generated_files_question(plan, "existing")["questions"][0]
    assert asked["id"] == GENERATED_QUESTION and asked["required"] is False
    assert "catalog-watch/openrouter-models.json linguist-generated=true" in asked["prompt"] and "cannot change .gitattributes" in asked["prompt"]
    marked = {**plan, "files": [{"path": ".gitattributes", "content": "catalog-watch/*.json linguist-generated\n"}]}
    assert generated_files_question(marked, "greenfield")["questions"] == []
    assert generated_files_question(marked, "existing")["questions"][0]["id"] == GENERATED_QUESTION
